// ─────────────────────────────────────────────────────────────────────────────────────────
// ANSI TELEMETRY HELPERS
// ─────────────────────────────────────────────────────────────────────────────────────────
const ANSI = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  dim: '\x1b[2m',
  cyan: '\x1b[36m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  magenta: '\x1b[35m',
  blue: '\x1b[34m',
  red: '\x1b[31m',
};

function logBanner(title: string, subtitle: string): void {
  console.log(`\n${ANSI.cyan}${ANSI.bold}╔══════════════════════════════════════════════════════════════════════════════════════════╗${ANSI.reset}`);
  console.log(`${ANSI.cyan}${ANSI.bold}║  ${title.padEnd(88, ' ')}║${ANSI.reset}`);
  console.log(`${ANSI.cyan}${ANSI.bold}║  ${ANSI.reset}${ANSI.yellow}${subtitle.padEnd(88, ' ')}${ANSI.cyan}${ANSI.bold}║${ANSI.reset}`);
  console.log(`${ANSI.cyan}${ANSI.bold}╚══════════════════════════════════════════════════════════════════════════════════════════╝${ANSI.reset}\n`);
}

function logStep(step: number, total: number, message: string): void {
  const pct = Math.round((step / total) * 100);
  const filled = Math.round(pct / 5);
  const bar = `${'█'.repeat(filled)}${'░'.repeat(20 - filled)}`;
  console.log(`${ANSI.blue}${ANSI.bold}[STEP ${step}/${total}]${ANSI.reset} ${ANSI.magenta}[${bar}] ${pct}%${ANSI.reset} — ${ANSI.bold}${message}${ANSI.reset}`);
}

function logSuccess(message: string): void {
  console.log(`  ${ANSI.green}✔${ANSI.reset} ${message}`);
}

