// ─────────────────────────────────────────────────────────────────────────────────────────
// CLSI C28-A3 DEMOGRAPHIC STRATIFICATION BUILDERS
// ─────────────────────────────────────────────────────────────────────────────────────────

/**
 * Generates full 6-tier CLSI C28-A3 age & sex stratified reference ranges
 * (Newborn 0-28d, Infant 29d-1y, Pediatric 1-12y, Adolescent 12-18y, Adult M/F 18-60y, Geriatric M/F 60-120y)
 */
function buildStratifiedRanges(opts: {
  adultMale: [number, number];
  adultFemale: [number, number];
  newborn?: [number, number];
  infant?: [number, number];
  pediatric?: [number, number];
  adolescent?: [number, number];
  geriatricMale?: [number, number];
  geriatricFemale?: [number, number];
  criticalLow?: number;
  criticalHigh?: number;
  unit?: string;
}): SeedReferenceRangeSpec[] {
  const [amLow, amHigh] = opts.adultMale;
  const [afLow, afHigh] = opts.adultFemale;
  const [nbLow, nbHigh] = opts.newborn ?? [Number((amLow * 0.95).toFixed(2)), Number((amHigh * 1.15).toFixed(2))];
  const [infLow, infHigh] = opts.infant ?? [Number((afLow * 0.88).toFixed(2)), Number((afHigh * 1.02).toFixed(2))];
  const [pedLow, pedHigh] = opts.pediatric ?? [Number((afLow * 0.92).toFixed(2)), Number((afHigh * 1.0).toFixed(2))];
  const [adoLow, adoHigh] = opts.adolescent ?? [afLow, amHigh];
  const [gmLow, gmHigh] = opts.geriatricMale ?? [amLow, amHigh];
  const [gfLow, gfHigh] = opts.geriatricFemale ?? [afLow, afHigh];

  const sanitizeCritLow = (nLow: number) =>
    opts.criticalLow !== undefined && opts.criticalLow < nLow ? opts.criticalLow : undefined;
  const sanitizeCritHigh = (nHigh: number) =>
    opts.criticalHigh !== undefined && opts.criticalHigh > nHigh ? opts.criticalHigh : undefined;

  return [
    {
      ageGroup: 'NEWBORN',
      gender: Gender.OTHER,
      minAge: 0,
      maxAge: 28,
      minAgeUnit: 'DAYS',
      maxAgeUnit: 'DAYS',
      normalLow: nbLow,
      normalHigh: nbHigh,
      criticalLow: sanitizeCritLow(nbLow),
      criticalHigh: sanitizeCritHigh(nbHigh),
      interpretation: 'CLSI C28-A3 Neonatal biological interval (0–28 days)',
      notes: `${nbLow} - ${nbHigh}${opts.unit ? ' ' + opts.unit : ''}`,
      displayOrder: 1,
    },
    {
      ageGroup: 'INFANT',
      gender: Gender.OTHER,
      minAge: 1,
      maxAge: 12,
      minAgeUnit: 'MONTHS',
      maxAgeUnit: 'MONTHS',
      normalLow: infLow,
      normalHigh: infHigh,
      criticalLow: sanitizeCritLow(infLow),
      criticalHigh: sanitizeCritHigh(infHigh),
      interpretation: 'CLSI C28-A3 Infant biological interval (29 days–1 year)',
      notes: `${infLow} - ${infHigh}${opts.unit ? ' ' + opts.unit : ''}`,
      displayOrder: 2,
    },
    {
      ageGroup: 'PEDIATRIC',
      gender: Gender.OTHER,
      minAge: 1,
      maxAge: 12,
      minAgeUnit: 'YEARS',
      maxAgeUnit: 'YEARS',
      normalLow: pedLow,
      normalHigh: pedHigh,
      criticalLow: sanitizeCritLow(pedLow),
      criticalHigh: sanitizeCritHigh(pedHigh),
      interpretation: 'CLSI C28-A3 Pediatric biological interval (1–12 years)',
      notes: `${pedLow} - ${pedHigh}${opts.unit ? ' ' + opts.unit : ''}`,
      displayOrder: 3,
    },
    {
      ageGroup: 'ADOLESCENT',
      gender: Gender.OTHER,
      minAge: 12,
      maxAge: 18,
      minAgeUnit: 'YEARS',
      maxAgeUnit: 'YEARS',
      normalLow: adoLow,
      normalHigh: adoHigh,
      criticalLow: sanitizeCritLow(adoLow),
      criticalHigh: sanitizeCritHigh(adoHigh),
      interpretation: 'CLSI C28-A3 Adolescent biological interval (12–18 years)',
      notes: `${adoLow} - ${adoHigh}${opts.unit ? ' ' + opts.unit : ''}`,
      displayOrder: 4,
    },
    {
      ageGroup: 'ADULT',
      gender: Gender.MALE,
      minAge: 18,
      maxAge: 60,
      minAgeUnit: 'YEARS',
      maxAgeUnit: 'YEARS',
      normalLow: amLow,
      normalHigh: amHigh,
      criticalLow: sanitizeCritLow(amLow),
      criticalHigh: sanitizeCritHigh(amHigh),
      interpretation: 'CLSI C28-A3 Adult Male biological interval (18–60 years)',
      notes: `${amLow} - ${amHigh}${opts.unit ? ' ' + opts.unit : ''}`,
      displayOrder: 5,
    },
    {
      ageGroup: 'ADULT',
      gender: Gender.FEMALE,
      minAge: 18,
      maxAge: 60,
      minAgeUnit: 'YEARS',
      maxAgeUnit: 'YEARS',
      normalLow: afLow,
      normalHigh: afHigh,
      criticalLow: sanitizeCritLow(afLow),
      criticalHigh: sanitizeCritHigh(afHigh),
      interpretation: 'CLSI C28-A3 Adult Female biological interval (18–60 years)',
      notes: `${afLow} - ${afHigh}${opts.unit ? ' ' + opts.unit : ''}`,
      displayOrder: 6,
    },
    {
      ageGroup: 'GERIATRIC',
      gender: Gender.MALE,
      minAge: 60,
      maxAge: 120,
      minAgeUnit: 'YEARS',
      maxAgeUnit: 'YEARS',
      normalLow: gmLow,
      normalHigh: gmHigh,
      criticalLow: sanitizeCritLow(gmLow),
      criticalHigh: sanitizeCritHigh(gmHigh),
      interpretation: 'CLSI C28-A3 Geriatric Male biological interval (>60 years)',
      notes: `${gmLow} - ${gmHigh}${opts.unit ? ' ' + opts.unit : ''}`,
      displayOrder: 7,
    },
    {
      ageGroup: 'GERIATRIC',
      gender: Gender.FEMALE,
      minAge: 60,
      maxAge: 120,
      minAgeUnit: 'YEARS',
      maxAgeUnit: 'YEARS',
      normalLow: gfLow,
      normalHigh: gfHigh,
      criticalLow: sanitizeCritLow(gfLow),
      criticalHigh: sanitizeCritHigh(gfHigh),
      interpretation: 'CLSI C28-A3 Geriatric Female biological interval (>60 years)',
      notes: `${gfLow} - ${gfHigh}${opts.unit ? ' ' + opts.unit : ''}`,
      displayOrder: 8,
    },
  ];
}

/**
 * Generates 3-tier age/sex reference ranges (Pediatric, Adult Male, Adult Female, Geriatric)
 * for standard clinical parameters.
 */
function buildStandardRanges(
  maleLow: number,
  maleHigh: number,
  femaleLow: number = maleLow,
  femaleHigh: number = maleHigh,
  criticalLow?: number,
  criticalHigh?: number,
  unit?: string
): SeedReferenceRangeSpec[] {
  const sLow = (nLow: number) => (criticalLow !== undefined && criticalLow < nLow ? criticalLow : undefined);
  const sHigh = (nHigh: number) => (criticalHigh !== undefined && criticalHigh > nHigh ? criticalHigh : undefined);

  return [
    {
      ageGroup: 'PEDIATRIC',
      gender: Gender.OTHER,
      minAge: 0,
      maxAge: 18,
      minAgeUnit: 'YEARS',
      maxAgeUnit: 'YEARS',
      normalLow: femaleLow,
      normalHigh: maleHigh,
      criticalLow: sLow(femaleLow),
      criticalHigh: sHigh(maleHigh),
      interpretation: 'CLSI C28-A3 Pediatric/Adolescent interval (0–18 years)',
      notes: `${femaleLow} - ${maleHigh}${unit ? ' ' + unit : ''}`,
      displayOrder: 1,
    },
    {
      ageGroup: 'ADULT',
      gender: Gender.MALE,
      minAge: 18,
      maxAge: 60,
      minAgeUnit: 'YEARS',
      maxAgeUnit: 'YEARS',
      normalLow: maleLow,
      normalHigh: maleHigh,
      criticalLow: sLow(maleLow),
      criticalHigh: sHigh(maleHigh),
      interpretation: 'CLSI C28-A3 Adult Male interval (18–60 years)',
      notes: `${maleLow} - ${maleHigh}${unit ? ' ' + unit : ''}`,
      displayOrder: 2,
    },
    {
      ageGroup: 'ADULT',
      gender: Gender.FEMALE,
      minAge: 18,
      maxAge: 60,
      minAgeUnit: 'YEARS',
      maxAgeUnit: 'YEARS',
      normalLow: femaleLow,
      normalHigh: femaleHigh,
      criticalLow: sLow(femaleLow),
      criticalHigh: sHigh(femaleHigh),
      interpretation: 'CLSI C28-A3 Adult Female interval (18–60 years)',
      notes: `${femaleLow} - ${femaleHigh}${unit ? ' ' + unit : ''}`,
      displayOrder: 3,
    },
    {
      ageGroup: 'GERIATRIC',
      gender: Gender.OTHER,
      minAge: 60,
      maxAge: 120,
      minAgeUnit: 'YEARS',
      maxAgeUnit: 'YEARS',
      normalLow: femaleLow,
      normalHigh: maleHigh,
      criticalLow: sLow(femaleLow),
      criticalHigh: sHigh(maleHigh),
      interpretation: 'CLSI C28-A3 Geriatric interval (>60 years)',
      notes: `${femaleLow} - ${maleHigh}${unit ? ' ' + unit : ''}`,
      displayOrder: 4,
    },
  ];
}

function buildQualitativeRange(expectedValue: string): SeedReferenceRangeSpec[] {
  return [
    {
      ageGroup: 'ALL_AGES',
      gender: Gender.OTHER,
      minAge: 0,
      maxAge: 120,
      minAgeUnit: 'YEARS',
      maxAgeUnit: 'YEARS',
      interpretation: `Normal / Expected: ${expectedValue}`,
      notes: expectedValue,
      displayOrder: 1,
    },
  ];
}

