// Expand compact tests and merge with primary panels to form the complete 160-test catalog
export const DAY6_TESTS: SeedTestSpec[] = [
  ...DAY6_PRIMARY_PANELS,
  ...COMPACT_CLINICAL_TESTS.map((def, idx): SeedTestSpec => ({
    testCode: def.code.trim(),
    testName: def.name,
    shortName: def.short,
    categoryCode: def.cat,
    sampleType: def.sample,
    sampleContainer: def.container,
    sampleVolume: def.vol,
    processingDepartment: def.dept,
    method: def.method,
    tatHours: def.tat,
    tatDisplay: def.tat >= 24 ? `${def.tat} Hours (${Math.round(def.tat / 24)} Days)` : `${def.tat} Hours`,
    price: def.price,
    offerPrice: def.offer,
    b2bRate: def.b2b,
    gstPercentage: 0,
    displayOrder: DAY6_PRIMARY_PANELS.length + idx + 1,
    clinicalSignificance: def.sig,
    patientPreparation: def.prep,
    description: `${def.name} (${def.code.trim()}) — NABL ISO 15189:2022 validated clinical examination in ${def.dept}.`,
    deltaCheckEnabled: def.params.some((p) => p.mLow !== undefined),
    deltaThresholdPercentage: 20,
    parameters: def.params.map((p, pIdx): SeedParameterSpec => {
      const isNumeric = p.mLow !== undefined && p.mHigh !== undefined;
      const dataType = isNumeric
        ? ParameterType.NUMERIC
        : p.options
        ? ParameterType.OPTION
        : ParameterType.TEXT;
      return {
        parameterName: p.name,
        shortName: p.short,
        loincCode: p.loinc,
        unit: p.unit,
        dataType,
        displayOrder: pIdx + 1,
        measurementMethod: def.method,
        dropdownOptions: p.options,
        decimalPrecision: isNumeric ? (Number.isInteger(p.mLow) && Number.isInteger(p.mHigh) ? 0 : 2) : undefined,
        isRequired: true,
        referenceRanges: isNumeric
          ? buildStandardRanges(
              p.mLow!,
              p.mHigh!,
              p.fLow ?? p.mLow!,
              p.fHigh ?? p.mHigh!,
              p.cLow,
              p.cHigh,
              p.unit
            )
          : buildQualitativeRange(p.qualitativeExpected ?? 'Normal / Negative'),
      };
    }),
  })),
];

