// ─────────────────────────────────────────────────────────────────────────────────────────
// 6. IDEMPOTENT CHUNKED TRANSACTION SEED ENGINE
// ─────────────────────────────────────────────────────────────────────────────────────────
export interface Day6SeedSummary {
  laboratorySettingsId: string;
  categoriesSeeded: number;
  testsSeeded: number;
  parametersSeeded: number;
  referenceRangesSeeded: number;
  packagesSeeded: number;
  packageItemsSeeded: number;
  organizationsSeeded: number;
  doctorsSeeded: number;
  elapsedMs: number;
}

export async function seedDay6ClinicalCatalog(): Promise<Day6SeedSummary> {
  const startTime = Date.now();

  logBanner(
    'NIKIL-LABCORE-ELIS-OS — DAY 6 CLINICAL CATALOG & ENTERPRISE DATA ENGINE',
    'Standards: NABL ISO 15189:2022 | CLSI C28-A3 | LOINC® | ICMR Panic Thresholds | GST 0%'
  );

  // ── STEP 1: Laboratory Settings (NABL ISO 15189:2022) ─────────────────────────────────
  logStep(1, 6, 'Seeding NABL ISO 15189:2022 Laboratory Settings & Governance...');
  const existingSettings = await prisma.laboratorySettings.findFirst();
  let labSettingsId: string;

  if (existingSettings) {
    const updated = await prisma.laboratorySettings.update({
      where: { id: existingSettings.id },
      data: {
        labName: DAY6_LABORATORY_SETTINGS.labName,
        labPhone: DAY6_LABORATORY_SETTINGS.labPhone,
        labEmail: DAY6_LABORATORY_SETTINGS.labEmail,
        labAddress: DAY6_LABORATORY_SETTINGS.labAddress,
        labCity: DAY6_LABORATORY_SETTINGS.labCity,
        labState: DAY6_LABORATORY_SETTINGS.labState,
        labPincode: DAY6_LABORATORY_SETTINGS.labPincode,
        nablAccreditation: DAY6_LABORATORY_SETTINGS.nablAccreditation,
        isoCertification: DAY6_LABORATORY_SETTINGS.isoCertification,
        gstin: DAY6_LABORATORY_SETTINGS.gstin,
        licenseNumber: DAY6_LABORATORY_SETTINGS.licenseNumber,
        laboratoryDirector: DAY6_LABORATORY_SETTINGS.laboratoryDirector,
        laboratoryDirectorQualification: DAY6_LABORATORY_SETTINGS.laboratoryDirectorQualification,
        pathologistInCharge: DAY6_LABORATORY_SETTINGS.pathologistInCharge,
        pathologistInChargeQualification: DAY6_LABORATORY_SETTINGS.pathologistInChargeQualification,
        reportIdPrefix: DAY6_LABORATORY_SETTINGS.reportIdPrefix,
        defaultAnalyzer: DAY6_LABORATORY_SETTINGS.defaultAnalyzer,
        defaultMethodology: DAY6_LABORATORY_SETTINGS.defaultMethodology,
        enableAutomatedNotifications: true,
        enablePatientNotifications: true,
        enableDoctorNotifications: true,
        enableAutoResultProcessing: true,
        enableLiveTelemetry: true,
      },
    });
    labSettingsId = updated.id;
  } else {
    const created = await prisma.laboratorySettings.create({
      data: DAY6_LABORATORY_SETTINGS,
    });
    labSettingsId = created.id;
  }
  logSuccess(
    `Lab Settings Active: ${DAY6_LABORATORY_SETTINGS.labName} | NABL: ${DAY6_LABORATORY_SETTINGS.nablAccreditation} | Prefix: ${DAY6_LABORATORY_SETTINGS.reportIdPrefix}`
  );

  // ── STEP 2: Accredited Clinical Categories (TestCategory) ────────────────────────────
  logStep(2, 6, `Seeding ${DAY6_CATEGORIES.length} Accredited Clinical Departments (TestCategory)...`);
  const categoryMap = new Map<string, string>();

  for (const cat of DAY6_CATEGORIES) {
    const upserted = await prisma.testCategory.upsert({
      where: { code: cat.code },
      update: {
        name: cat.name,
        department: cat.department,
        description: cat.description,
        color: cat.color,
        icon: cat.icon,
        displayOrder: cat.displayOrder,
        isActive: true,
      },
      create: {
        code: cat.code,
        name: cat.name,
        department: cat.department,
        description: cat.description,
        color: cat.color,
        icon: cat.icon,
        displayOrder: cat.displayOrder,
        isActive: true,
      },
    });
    categoryMap.set(cat.code, upserted.id);
  }
  logSuccess(`Seeded ${categoryMap.size} Clinical Departments (${Array.from(categoryMap.keys()).join(', ')})`);

  // ── STEP 3: 160 Diagnostic Tests, 460+ Parameters & 950+ CLSI C28-A3 Ranges ──────────
  logStep(
    3,
    6,
    `Seeding ${DAY6_TESTS.length} Diagnostic Tests, Parameters & CLSI C28-A3 Reference Ranges in Batched Transactions...`
  );

  const testIdMap = new Map<string, { id: string; price: number }>();
  let totalParametersSeeded = 0;
  let totalRangesSeeded = 0;

  const CHUNK_SIZE = 20;
  for (let i = 0; i < DAY6_TESTS.length; i += CHUNK_SIZE) {
    const chunk = DAY6_TESTS.slice(i, i + CHUNK_SIZE);

    await prisma.$transaction(
      async (tx) => {
        for (const testSpec of chunk) {
          const categoryId = categoryMap.get(testSpec.categoryCode) ?? null;

          const upsertedTest = await tx.test.upsert({
            where: { testCode: testSpec.testCode },
            update: {
              testName: testSpec.testName,
              shortName: testSpec.shortName,
              categoryId,
              sampleType: testSpec.sampleType,
              sampleContainer: testSpec.sampleContainer,
              sampleVolume: testSpec.sampleVolume,
              processingDepartment: testSpec.processingDepartment,
              method: testSpec.method,
              tatHours: testSpec.tatHours,
              tatDisplay: testSpec.tatDisplay,
              price: new Prisma.Decimal(testSpec.price),
              offerPrice: new Prisma.Decimal(testSpec.offerPrice),
              b2bRate: new Prisma.Decimal(testSpec.b2bRate),
              gstPercentage: new Prisma.Decimal(testSpec.gstPercentage),
              displayOrder: testSpec.displayOrder,
              clinicalSignificance: testSpec.clinicalSignificance,
              patientPreparation: testSpec.patientPreparation,
              description: testSpec.description,
              deltaCheckEnabled: testSpec.deltaCheckEnabled ?? false,
              deltaThresholdPercentage:
                testSpec.deltaThresholdPercentage !== undefined
                  ? new Prisma.Decimal(testSpec.deltaThresholdPercentage)
                  : null,
              isActive: true,
            },
            create: {
              testCode: testSpec.testCode,
              testName: testSpec.testName,
              shortName: testSpec.shortName,
              categoryId,
              sampleType: testSpec.sampleType,
              sampleContainer: testSpec.sampleContainer,
              sampleVolume: testSpec.sampleVolume,
              processingDepartment: testSpec.processingDepartment,
              method: testSpec.method,
              tatHours: testSpec.tatHours,
              tatDisplay: testSpec.tatDisplay,
              price: new Prisma.Decimal(testSpec.price),
              offerPrice: new Prisma.Decimal(testSpec.offerPrice),
              b2bRate: new Prisma.Decimal(testSpec.b2bRate),
              gstPercentage: new Prisma.Decimal(testSpec.gstPercentage),
              displayOrder: testSpec.displayOrder,
              clinicalSignificance: testSpec.clinicalSignificance,
              patientPreparation: testSpec.patientPreparation,
              description: testSpec.description,
              deltaCheckEnabled: testSpec.deltaCheckEnabled ?? false,
              deltaThresholdPercentage:
                testSpec.deltaThresholdPercentage !== undefined
                  ? new Prisma.Decimal(testSpec.deltaThresholdPercentage)
                  : null,
              isActive: true,
            },
          });

          testIdMap.set(testSpec.testCode, { id: upsertedTest.id, price: testSpec.price });

          for (const paramSpec of testSpec.parameters) {
            const existingParam = await tx.testParameter.findFirst({
              where: {
                testId: upsertedTest.id,
                parameterName: paramSpec.parameterName,
              },
            });

            let paramId: string;
            if (existingParam) {
              const updatedParam = await tx.testParameter.update({
                where: { id: existingParam.id },
                data: {
                  shortName: paramSpec.shortName,
                  loincCode: paramSpec.loincCode,
                  unit: paramSpec.unit,
                  dataType: paramSpec.dataType,
                  displayOrder: paramSpec.displayOrder,
                  measurementMethod: paramSpec.measurementMethod ?? testSpec.method,
                  dropdownOptions: paramSpec.dropdownOptions ?? null,
                  decimalPrecision: paramSpec.decimalPrecision ?? null,
                  isRequired: paramSpec.isRequired ?? true,
                  isActive: true,
                },
              });
              paramId = updatedParam.id;
            } else {
              const createdParam = await tx.testParameter.create({
                data: {
                  testId: upsertedTest.id,
                  parameterName: paramSpec.parameterName,
                  shortName: paramSpec.shortName,
                  loincCode: paramSpec.loincCode,
                  unit: paramSpec.unit,
                  dataType: paramSpec.dataType,
                  displayOrder: paramSpec.displayOrder,
                  measurementMethod: paramSpec.measurementMethod ?? testSpec.method,
                  dropdownOptions: paramSpec.dropdownOptions ?? null,
                  decimalPrecision: paramSpec.decimalPrecision ?? null,
                  isRequired: paramSpec.isRequired ?? true,
                  isActive: true,
                },
              });
              paramId = createdParam.id;
            }
            totalParametersSeeded++;

            // Cleanly replace reference ranges for this parameter so re-runs never duplicate ranges
            await tx.referenceRange.deleteMany({
              where: { parameterId: paramId },
            });

            if (paramSpec.referenceRanges.length > 0) {
              await tx.referenceRange.createMany({
                data: paramSpec.referenceRanges.map((rr, rrIdx) => ({
                  parameterId: paramId,
                  ageGroup: rr.ageGroup,
                  gender: rr.gender ?? Gender.OTHER,
                  minAge: rr.minAge,
                  maxAge: rr.maxAge,
                  minAgeUnit: rr.minAgeUnit,
                  maxAgeUnit: rr.maxAgeUnit,
                  normalLow: rr.normalLow !== undefined ? new Prisma.Decimal(rr.normalLow) : null,
                  normalHigh: rr.normalHigh !== undefined ? new Prisma.Decimal(rr.normalHigh) : null,
                  criticalLow: rr.criticalLow !== undefined ? new Prisma.Decimal(rr.criticalLow) : null,
                  criticalHigh: rr.criticalHigh !== undefined ? new Prisma.Decimal(rr.criticalHigh) : null,
                  interpretation: rr.interpretation ?? null,
                  notes: rr.notes ?? null,
                  displayOrder: rr.displayOrder ?? rrIdx + 1,
                  isActive: true,
                })),
              });
              totalRangesSeeded += paramSpec.referenceRanges.length;
            }
          }
        }
      },
      { timeout: 60000 }
    );

    const processed = Math.min(i + CHUNK_SIZE, DAY6_TESTS.length);
    console.log(
      `    ${ANSI.dim}↳ Batch ${Math.ceil(processed / CHUNK_SIZE)}/${Math.ceil(
        DAY6_TESTS.length / CHUNK_SIZE
      )}: ${processed}/${DAY6_TESTS.length} tests committed (${totalParametersSeeded} params, ${totalRangesSeeded} ranges)${ANSI.reset}`
    );
  }

  logSuccess(
    `Catalog Seeded: ${testIdMap.size} Diagnostic Tests | ${totalParametersSeeded} LOINC Parameters | ${totalRangesSeeded} CLSI C28-A3 Reference Ranges`
  );

  // ── STEP 4: Preventive Health Checkup Packages (TestPackage & TestPackageItem) ───────
  logStep(4, 6, `Seeding ${DAY6_PACKAGES.length} Preventive Health Checkup Packages & Bundled Pricing...`);
  let totalPackageItemsSeeded = 0;

  for (const pkgSpec of DAY6_PACKAGES) {
    const resolvedItems = pkgSpec.testCodes
      .map((code) => ({ code, meta: testIdMap.get(code) }))
      .filter((item): item is { code: string; meta: { id: string; price: number } } => Boolean(item.meta));

    const totalPrice = resolvedItems.reduce((acc, item) => acc + item.meta.price, 0);
    const offerPrice = Math.min(pkgSpec.offerPrice, totalPrice);
    const discountPercentage =
      totalPrice > 0 ? Number((((totalPrice - offerPrice) / totalPrice) * 100).toFixed(2)) : 0;

    const upsertedPkg = await prisma.testPackage.upsert({
      where: { packageCode: pkgSpec.packageCode },
      update: {
        packageName: pkgSpec.packageName,
        description: pkgSpec.description,
        totalPrice: new Prisma.Decimal(totalPrice),
        offerPrice: new Prisma.Decimal(offerPrice),
        discountPercentage: new Prisma.Decimal(discountPercentage),
        gstPercentage: new Prisma.Decimal(0),
        includesTestsCount: resolvedItems.length,
        tatHours: pkgSpec.tatHours,
        tatDisplay: pkgSpec.tatDisplay,
        targetAudience: pkgSpec.targetAudience,
        recommendedFor: pkgSpec.recommendedFor,
        isPopular: pkgSpec.isPopular,
        displayOrder: pkgSpec.displayOrder,
        color: pkgSpec.color,
        icon: pkgSpec.icon,
        isActive: true,
      },
      create: {
        packageCode: pkgSpec.packageCode,
        packageName: pkgSpec.packageName,
        description: pkgSpec.description,
        totalPrice: new Prisma.Decimal(totalPrice),
        offerPrice: new Prisma.Decimal(offerPrice),
        discountPercentage: new Prisma.Decimal(discountPercentage),
        gstPercentage: new Prisma.Decimal(0),
        includesTestsCount: resolvedItems.length,
        tatHours: pkgSpec.tatHours,
        tatDisplay: pkgSpec.tatDisplay,
        targetAudience: pkgSpec.targetAudience,
        recommendedFor: pkgSpec.recommendedFor,
        isPopular: pkgSpec.isPopular,
        displayOrder: pkgSpec.displayOrder,
        color: pkgSpec.color,
        icon: pkgSpec.icon,
        isActive: true,
      },
    });

    for (let idx = 0; idx < resolvedItems.length; idx++) {
      const item = resolvedItems[idx];
      const perItemDiscount = Number(((item.meta.price * discountPercentage) / 100).toFixed(2));

      await prisma.testPackageItem.upsert({
        where: {
          packageId_testId: {
            packageId: upsertedPkg.id,
            testId: item.meta.id,
          },
        },
        update: {
          testPrice: new Prisma.Decimal(item.meta.price),
          discount: new Prisma.Decimal(perItemDiscount),
          displayOrder: idx + 1,
        },
        create: {
          packageId: upsertedPkg.id,
          testId: item.meta.id,
          testPrice: new Prisma.Decimal(item.meta.price),
          discount: new Prisma.Decimal(perItemDiscount),
          displayOrder: idx + 1,
        },
      });
      totalPackageItemsSeeded++;
    }
  }
  logSuccess(`Seeded ${DAY6_PACKAGES.length} Health Checkup Packages with ${totalPackageItemsSeeded} Bundled Test Items`);

  // ── STEP 5: Partner Healthcare Organizations (DoctorOrganization) ────────────────────
  logStep(5, 6, `Seeding ${DAY6_DOCTOR_ORGANIZATIONS.length} Partner Hospitals & Referral Organizations...`);
  const orgIdMap = new Map<string, string>();

  for (const orgSpec of DAY6_DOCTOR_ORGANIZATIONS) {
    const upsertedOrg = await prisma.doctorOrganization.upsert({
      where: { code: orgSpec.code },
      update: {
        name: orgSpec.name,
        organizationType: orgSpec.organizationType,
        contactPerson: orgSpec.contactPerson,
        phone: orgSpec.phone,
        email: orgSpec.email,
        address: orgSpec.address,
        city: orgSpec.city,
        state: orgSpec.state,
        pincode: orgSpec.pincode,
        gstin: orgSpec.gstin,
        panNumber: orgSpec.panNumber,
        commissionRate: new Prisma.Decimal(orgSpec.commissionRate),
        payoutCycle: orgSpec.payoutCycle,
        bankAccountNumber: orgSpec.bankAccountNumber,
        bankIfscCode: orgSpec.bankIfscCode,
        bankAccountHolderName: orgSpec.bankAccountHolderName,
        isActive: true,
      },
      create: {
        code: orgSpec.code,
        name: orgSpec.name,
        organizationType: orgSpec.organizationType,
        contactPerson: orgSpec.contactPerson,
        phone: orgSpec.phone,
        email: orgSpec.email,
        address: orgSpec.address,
        city: orgSpec.city,
        state: orgSpec.state,
        pincode: orgSpec.pincode,
        gstin: orgSpec.gstin,
        panNumber: orgSpec.panNumber,
        commissionRate: new Prisma.Decimal(orgSpec.commissionRate),
        payoutCycle: orgSpec.payoutCycle,
        bankAccountNumber: orgSpec.bankAccountNumber,
        bankIfscCode: orgSpec.bankIfscCode,
        bankAccountHolderName: orgSpec.bankAccountHolderName,
        isActive: true,
      },
    });
    orgIdMap.set(orgSpec.code, upsertedOrg.id);
  }
  logSuccess(`Seeded ${orgIdMap.size} Partner Healthcare Organizations`);

  // ── STEP 6: 24 Multi-Specialty Referring & Consulting Doctors (Doctor) ───────────────
  logStep(6, 6, `Seeding ${DAY6_DOCTORS.length} Multi-Specialty Referring & Signatory Doctors...`);
  let doctorsSeeded = 0;

  for (const docSpec of DAY6_DOCTORS) {
    const organizationId = docSpec.organizationCode ? orgIdMap.get(docSpec.organizationCode) ?? null : null;

    await prisma.doctor.upsert({
      where: { doctorCode: docSpec.doctorCode },
      update: {
        title: docSpec.title,
        fullName: docSpec.fullName,
        gender: docSpec.gender,
        qualification: docSpec.qualification,
        specialization: docSpec.specialization,
        department: docSpec.department,
        designation: docSpec.designation,
        registrationNumber: docSpec.registrationNumber,
        licenseNumber: docSpec.registrationNumber,
        registrationCouncil: docSpec.registrationCouncil,
        experience: docSpec.experienceYears,
        experienceYears: docSpec.experienceYears,
        phone: docSpec.phone,
        whatsappNumber: docSpec.whatsappNumber,
        email: docSpec.email,
        clinicName: docSpec.clinicName,
        address: docSpec.clinicAddress,
        clinicAddress: docSpec.clinicAddress,
        city: docSpec.city,
        state: docSpec.state,
        pincode: docSpec.pincode,
        doctorType: docSpec.doctorType,
        commissionType: docSpec.commissionType,
        commissionRate: docSpec.commissionRate !== undefined ? new Prisma.Decimal(docSpec.commissionRate) : null,
        commissionFlatAmount:
          docSpec.commissionFlatAmount !== undefined ? new Prisma.Decimal(docSpec.commissionFlatAmount) : null,
        payoutCycle: docSpec.payoutCycle,
        bankName: docSpec.bankName,
        bankAccountNumber: docSpec.bankAccountNumber,
        bankIfscCode: docSpec.bankIfscCode,
        bankAccountHolderName: docSpec.bankAccountHolderName,
        upiId: docSpec.upiId,
        panNumber: docSpec.panNumber,
        consultationFee: new Prisma.Decimal(docSpec.consultationFee),
        organizationId,
        reportDeliveryEmail: true,
        reportDeliveryWhatsApp: true,
        reportDeliveryPortal: true,
        enablePortalAccess: true,
        isActive: true,
        isArchived: false,
      },
      create: {
        doctorCode: docSpec.doctorCode,
        title: docSpec.title,
        fullName: docSpec.fullName,
        gender: docSpec.gender,
        qualification: docSpec.qualification,
        specialization: docSpec.specialization,
        department: docSpec.department,
        designation: docSpec.designation,
        registrationNumber: docSpec.registrationNumber,
        licenseNumber: docSpec.registrationNumber,
        registrationCouncil: docSpec.registrationCouncil,
        experience: docSpec.experienceYears,
        experienceYears: docSpec.experienceYears,
        phone: docSpec.phone,
        whatsappNumber: docSpec.whatsappNumber,
        email: docSpec.email,
        clinicName: docSpec.clinicName,
        address: docSpec.clinicAddress,
        clinicAddress: docSpec.clinicAddress,
        city: docSpec.city,
        state: docSpec.state,
        pincode: docSpec.pincode,
        doctorType: docSpec.doctorType,
        commissionType: docSpec.commissionType,
        commissionRate: docSpec.commissionRate !== undefined ? new Prisma.Decimal(docSpec.commissionRate) : null,
        commissionFlatAmount:
          docSpec.commissionFlatAmount !== undefined ? new Prisma.Decimal(docSpec.commissionFlatAmount) : null,
        payoutCycle: docSpec.payoutCycle,
        bankName: docSpec.bankName,
        bankAccountNumber: docSpec.bankAccountNumber,
        bankIfscCode: docSpec.bankIfscCode,
        bankAccountHolderName: docSpec.bankAccountHolderName,
        upiId: docSpec.upiId,
        panNumber: docSpec.panNumber,
        consultationFee: new Prisma.Decimal(docSpec.consultationFee),
        organizationId,
        reportDeliveryEmail: true,
        reportDeliveryWhatsApp: true,
        reportDeliveryPortal: true,
        enablePortalAccess: true,
        isActive: true,
        isArchived: false,
      },
    });
    doctorsSeeded++;
  }
  logSuccess(`Seeded ${doctorsSeeded} Multi-Specialty Doctors (KMC, MMC, DMC, TNMC, APMC, GMC, TCMC, WBMC)`);

  const elapsedMs = Date.now() - startTime;
  console.log(`\n${ANSI.green}${ANSI.bold}══════════════════════════════════════════════════════════════════════════════════════════${ANSI.reset}`);
  console.log(`${ANSI.green}${ANSI.bold}🎉 DAY 6 CLINICAL CATALOG SEEDING COMPLETED SUCCESSFULLY IN ${(elapsedMs / 1000).toFixed(2)}s!${ANSI.reset}`);
  console.log(`   • Laboratory Governance : ${DAY6_LABORATORY_SETTINGS.labName} (NABL ${DAY6_LABORATORY_SETTINGS.nablAccreditation})`);
  console.log(`   • Accredited Categories : ${categoryMap.size}`);
  console.log(`   • Diagnostic Tests      : ${testIdMap.size}`);
  console.log(`   • Test Parameters       : ${totalParametersSeeded} (100% LOINC®-mapped)`);
  console.log(`   • Reference Ranges      : ${totalRangesSeeded} (CLSI C28-A3 Stratified + ICMR Panic Bounds)`);
  console.log(`   • Wellness Packages     : ${DAY6_PACKAGES.length} (${totalPackageItemsSeeded} Bundled Items)`);
  console.log(`   • Partner Organizations : ${orgIdMap.size}`);
  console.log(`   • Referring Doctors     : ${doctorsSeeded}`);
  console.log(`${ANSI.green}${ANSI.bold}══════════════════════════════════════════════════════════════════════════════════════════${ANSI.reset}\n`);

  return {
    laboratorySettingsId: labSettingsId,
    categoriesSeeded: categoryMap.size,
    testsSeeded: testIdMap.size,
    parametersSeeded: totalParametersSeeded,
    referenceRangesSeeded: totalRangesSeeded,
    packagesSeeded: DAY6_PACKAGES.length,
    packageItemsSeeded: totalPackageItemsSeeded,
    organizationsSeeded: orgIdMap.size,
    doctorsSeeded,
    elapsedMs,
  };
}

// Execute automatically when run directly via `npx tsx backend/scripts/seed-day6-clinical-catalog.ts`
if (require.main === module) {
  seedDay6ClinicalCatalog()
    .then(async () => {
      await prisma.$disconnect();
      process.exit(0);
    })
    .catch(async (error) => {
      console.error(`${ANSI.red}❌ Fatal Error during Day 6 Clinical Catalog Seeding:${ANSI.reset}`, error);
      await prisma.$disconnect();
      process.exit(1);
    });
}